import type { ExpansionSpec } from './types';
import type { Spec } from '../author';
const refs:Record<string,[string,string]>={Immunology:['Immunobiology, 5th edition; further reading','https://www.ncbi.nlm.nih.gov/books/NBK10757/'],Genetics:['MedlinePlus Genetics: Help Me Understand Genetics','https://medlineplus.gov/genetics/understanding/'],Microbiology:['Medical Microbiology, 4th edition; further reading','https://www.ncbi.nlm.nih.gov/books/NBK7627/']};
let number=100;
function q(subject:string,system:string,topic:string,difficulty:1|2|3,stem:string,options:Spec['options'],explanation:string,objective:string,closest:string):ExpansionSpec{const reference=refs[subject];if(!reference)throw new Error('Unknown expansion subject: '+subject);return {code:`op26x-${String(++number).padStart(4,'0')}`,concept:topic.toLowerCase().replace(/[^a-z0-9]+/g,'-'),reasoning:({1:'recognition',2:'application',3:'integration'} as const)[difficulty],difficultyReason:`${difficulty===1?'Identify the explicitly cued biological process':difficulty===2?'Apply the stated molecular or cellular mechanism':'Integrate independent findings and infer the intermediate defect'}: ${objective}`,evidenceNote:'NIH indexed bibliographic identity and broad topic coverage checked. Indexed Immunobiology antigen-processing and T-cell activation chapters confirmed TAP/invariant-chain and CD28/B7 concepts; MedlinePlus variant definitions were checked. Other items have book-level further reading, not option-level or clinician validation; direct NCBI requests encountered human verification.',semanticReviewNote:`Closest prior topic: ${closest}. Distinct objective: ${objective}`,concerns:[],question:{subject,system,topic,difficulty,exam:'Step 1',stem,options,explanation,objective,reference}};}
export const specs:ExpansionSpec[]=[
q('Immunology','General Principles','TAP peptide transport',2,'A cell degrades cytosolic proteins normally but cannot efficiently move resulting peptides into the ER for class I loading. Which transporter is defective?',[
['TAP','TAP transports cytosolic peptides into the ER for class I loading.'],['Invariant chain','Invariant chain guides class II trafficking rather than importing these peptides.'],['CD28','CD28 provides T-cell costimulation rather than ER peptide transport.'],['C3 convertase','This complement enzyme does not transport peptides across the ER membrane.']],
'Proteasomal peptides must reach the ER to bind newly assembled class I molecules. TAP performs ATP-dependent transport across the ER membrane. Defective transport reduces stable peptide-loaded class I display despite preserved production of peptide fragments in the cytosol.','Identify TAP-dependent ER entry as a distinct class I processing step.','generic class I antigen presentation'),
q('Immunology','General Principles','Invariant chain groove protection',2,'New class II molecules in the ER must avoid binding available ER peptides before reaching endosomes. Which associated protein initially occupies and protects their groove?',[
['Invariant chain','Invariant chain blocks premature loading and directs class II molecules toward endosomes.'],['Beta-2 microglobulin','This is associated with class I rather than the class II invariant-chain role.'],['Perforin','Perforin participates in cytotoxic killing rather than class II trafficking.'],['C9','C9 forms complement pores rather than blocking a class II groove.']],
'Invariant chain associates with newly synthesized class II molecules, protecting their peptide-binding groove and directing endosomal trafficking. Proteolysis leaves CLIP in the groove until peptide exchange occurs. This compartmentalization favors loading of peptides derived from endosomal proteins.','Explain invariant-chain prevention of premature class II peptide loading.','generic antigen presentation'),
q('Immunology','General Principles','HLA-DM peptide exchange',2,'An antigen-presenting cell reaches an acidic endosomal compartment but retains CLIP in class II grooves. Which molecule normally facilitates CLIP release and peptide exchange?',[
['HLA-DM','HLA-DM promotes exchange of CLIP for suitable antigenic peptides.'],['TAP','TAP transports cytosolic peptides into the ER for class I loading.'],['CD8','CD8 is a class I-associated T-cell coreceptor rather than this editing molecule.'],['IgE','IgE binds mast-cell receptors and does not catalyze class II peptide exchange.']],
'Invariant-chain degradation leaves CLIP bound to class II. HLA-DM assists removal and exchange for endosomal peptides, helping select stable complexes for surface display. A failure at this step differs from absent antigen uptake or failure to transport cytosolic peptides through TAP.','Identify HLA-DM-mediated CLIP exchange in class II processing.','class II cellular distribution'),
q('Immunology','General Principles','Dendritic cross-presentation',3,'A dendritic cell takes up material from an infected dying cell and activates naive CD8 T cells without itself being infected. Which presentation process explains this?',[
['Cross-presentation of exogenous antigen on class I','Dendritic cells can route acquired extracellular antigens into class I presentation.'],['Presentation on class II to CD8 alone','Conventional CD8 recognition is associated with class I rather than class II.'],['Antibody gene transfer into the T cell','T-cell priming does not require acquisition of antibody genes.'],['Direct infection of every responding T cell','The described priming can occur without infecting the T cells.']],
'Some dendritic cells can present acquired extracellular material on class I molecules. This cross-presentation allows CD8 priming against infected tissues that do not directly infect the presenting cell. It bridges antigen acquisition and cytotoxic T-cell activation without changing coreceptor specificity.','Integrate extracellular antigen uptake with class I-dependent CD8 priming.','class I versus class II recognition'),
q('Immunology','General Principles','CD28 costimulatory requirement',2,'A naive T cell recognizes peptide-MHC on an antigen-presenting cell lacking B7 molecules. Which missing interaction normally supports full activation?',[
['B7 binding to CD28','B7 ligands provide a major costimulatory signal through T-cell CD28.'],['C9 binding to hemoglobin','This interaction is not a physiologic T-cell costimulation mechanism.'],['IgE binding to erythrocytes','IgE-mediated red-cell binding does not provide the required naive T-cell signal.'],['Intrinsic factor binding to class I','Intrinsic factor is a digestive binding protein rather than a costimulatory ligand.']],
'Naive T-cell activation normally requires antigen-receptor recognition plus costimulation. B7 molecules on activated antigen-presenting cells bind CD28 and support survival and proliferation. Antigen recognition without adequate costimulation can favor nonresponsiveness rather than a complete productive response.','Identify B7-CD28 as a major naive T-cell costimulatory interaction.','antigen presentation alone'),
q('Immunology','General Principles','CTLA-4 activation restraint',2,'An activated T cell increases expression of a receptor that binds B7 and limits subsequent activation. Which receptor provides this inhibitory checkpoint?',[
['CTLA-4','CTLA-4 binds B7 and restrains T-cell activation.'],['CD28','CD28 primarily provides positive rather than inhibitory costimulation.'],['CD3','CD3 transduces antigen-receptor signals rather than serving as the B7 inhibitory receptor.'],['CD19','CD19 is a B-cell coreceptor component rather than this T-cell checkpoint.']],
'Activated T cells increase CTLA-4 expression as part of feedback restraint. CTLA-4 engages B7 and limits activation, in contrast with the positive signal supplied through CD28. Similar ligand recognition can therefore lead to different effects depending on the T-cell receptor involved.','Distinguish CTLA-4 restraint from CD28 costimulation.','T-cell activation requirement'),
q('Immunology','General Principles','Thymic positive selection',2,'Developing thymocytes fail to recognize any self-MHC molecule with sufficient affinity. Which developmental outcome is most likely in normal positive selection?',[
['Death by neglect','Cells without usable self-MHC recognition fail to receive survival signals.'],['Automatic differentiation into every effector lineage','A usable receptor signal is needed before normal T-cell maturation.'],['Immediate production of class-switched antibodies','Thymocytes are not antibody-producing B cells.'],['Preferential survival solely because recognition is absent','Absent recognition fails the positive-selection requirement.']],
'Positive selection preserves thymocytes whose receptors can recognize self-MHC sufficiently to receive survival signals. Cells lacking usable recognition undergo death by neglect. This is different from negative selection, which removes many cells with excessively strong self-reactivity.','Explain loss of thymocytes that cannot recognize self-MHC during positive selection.','thymic developmental absence'),
q('Immunology','General Principles','AIRE tissue antigen display',2,'A thymic epithelial defect reduces expression of proteins normally restricted to peripheral tissues. Which tolerance process is most directly weakened?',[
['Deletion of strongly self-reactive developing T cells','Tissue-antigen display helps eliminate thymocytes that could attack peripheral tissues.'],['Formation of bacterial capsules','Thymic epithelial proteins do not produce bacterial capsules.'],['Transport of IgA through intestinal epithelium','Mucosal antibody transport is not the thymic antigen-display function.'],['Class I peptide movement through TAP','Tissue-antigen transcription is distinct from the ER transporter itself.']],
'AIRE promotes expression of many tissue-restricted antigens in medullary thymic epithelial cells. Their display supports central tolerance by exposing developing T cells to peripheral self components. Reduced display can permit escape of autoreactive clones despite an anatomically present thymus.','Connect AIRE-dependent tissue antigen display to central T-cell tolerance.','thymic development'),
q('Immunology','General Principles','B-cell receptor editing',2,'An immature marrow B cell strongly recognizes self antigen and resumes light-chain gene rearrangement. What tolerance mechanism is this cell attempting?',[
['Receptor editing','New light-chain rearrangement can change specificity away from the self antigen.'],['Class switching alone','Changing the constant region does not ordinarily change antigen-binding specificity.'],['Somatic mutation of every T-cell receptor','The described cell is a B cell altering its light-chain rearrangement.'],['Complement membrane attack','Complement lysis does not repair a self-reactive antigen receptor.']],
'Immature self-reactive B cells can reactivate light-chain rearrangement to produce a different receptor. Successful editing may remove self-reactivity and permit survival. This changes antigen-binding specificity and differs from class switching, which mainly changes antibody effector function.','Explain light-chain receptor editing as a central B-cell tolerance mechanism.','CD40-dependent class switching'),
q('Immunology','General Principles','Follicular affinity maturation',2,'After repeated exposure to one protein antigen, antibodies bind it more tightly even when compared within the same isotype. Which process explains the increased affinity?',[
['Selection of somatically mutated variable regions','Germinal-center mutation and selection enrich higher-affinity B-cell clones.'],['Constant-region switching as the sole explanation','Switching isotype changes effector function rather than directly increasing binding affinity.'],['Replacement of all antibodies by complement','Complement does not become the antigen-binding variable region.'],['Loss of every antigen-specific B cell','Eliminating all specific clones would not improve antigen-specific affinity.']],
'Activated B cells undergo somatic hypermutation in immunoglobulin variable-region genes. Competition for antigen and T-cell help selects clones with improved binding. This affinity maturation can occur alongside class switching, but the two processes change different antibody properties.','Separate variable-region affinity maturation from constant-region class switching.','class switching defect'),
q('Immunology','General Principles','Primary versus secondary IgG response',3,'Two blood samples follow first and later exposure to the same antigen. The later response is faster and includes higher-affinity IgG. Which cellular population best explains this?',[
['Antigen-experienced memory B cells','Memory cells respond rapidly and can generate affinity-matured antibody output.'],['Only newly produced naive erythrocytes','Red cells do not provide antigen-specific immunoglobulin memory.'],['Every resting neutrophil','Neutrophils lack the clonally rearranged antibody memory system.'],['Only unselected self-reactive thymocytes','These are not the source of the observed B-cell antibody memory.']],
'Primary responses establish memory B cells after antigen-driven expansion and selection. On re-exposure, these cells respond more rapidly and can produce class-switched, higher-affinity antibodies. The combination of timing and affinity distinguishes memory from simply increasing nonspecific inflammatory cells.','Integrate response speed and antibody affinity as evidence of B-cell memory.','class switching'),
q('Immunology','General Principles','Secretory IgA epithelial transport',2,'A dimeric antibody made beneath intestinal epithelium enters the lumen with a secretory component attached. Which receptor mediates its epithelial transcytosis?',[
['Polymeric immunoglobulin receptor','This receptor transports polymeric IgA across mucosal epithelium.'],['Neonatal Fc receptor as the IgA-specific route','FcRn chiefly handles IgG and is not the principal polymeric IgA transporter.'],['CD28','CD28 mediates T-cell costimulation rather than epithelial antibody export.'],['TAP','TAP transports peptides across the ER membrane rather than intact IgA.']],
'Dimeric IgA containing a J chain binds the polymeric immunoglobulin receptor basolaterally. Transcytosis and receptor cleavage release secretory IgA into the lumen with a protective secretory component. Mucosal antibody production and epithelial delivery are therefore distinct steps.','Identify polymeric immunoglobulin receptor transport of secretory IgA.','immunoglobulin class switching'),
q('Immunology','General Principles','Placental IgG FcRn transport',1,'Maternal antibody crosses the placenta and provides temporary systemic protection to a newborn. Which antibody class is preferentially transferred through Fc receptor-mediated transport?',[
['IgG','Placental FcRn-mediated transport preferentially transfers maternal IgG.'],['IgM','The large pentameric IgM molecule is not normally transferred efficiently across placenta.'],['IgE','IgE is not the principal antibody class transferred for systemic neonatal protection.'],['Dimeric secretory IgA','Secretory IgA principally supports mucosal protection rather than placental systemic transfer.']],
'Maternal IgG is transported across the placenta through Fc receptor-dependent pathways, providing passive systemic immunity. The infant did not generate this antibody through its own antigen response. This protection wanes as maternal IgG is cleared after birth.','Identify IgG as the major placentally transferred antibody class.','mucosal IgA transport'),
q('Immunology','General Principles','Classical complement initiation',2,'Antigen-bound IgM exposes complement-binding sites and initiates the classical pathway. Which complement component first recognizes the antibody Fc arrangement?',[
['C1q','C1q binds appropriately arranged Fc regions in antigen-antibody complexes.'],['C9','C9 acts at the terminal membrane attack stage rather than initial recognition.'],['Factor D','Factor D functions in alternative-pathway convertase formation.'],['Mannose-binding lectin','This recognizes microbial carbohydrates in the lectin rather than antibody classical pathway.']],
'C1q recognizes Fc regions arranged by antigen-bound antibody, activating associated C1 proteases and the classical cascade. Subsequent steps generate convertases and effector fragments. Initial antibody recognition therefore differs from alternative-pathway amplification and terminal pore formation.','Identify C1q as the recognition component of antibody-initiated complement.','terminal complement deficiency'),
q('Immunology','General Principles','C3b opsonization function',2,'Bacteria coated with a complement fragment are engulfed more efficiently through phagocyte complement receptors. Which fragment principally provides this opsonizing signal?',[
['C3b','Surface-bound C3b tags particles for recognition by complement receptors.'],['C3a','C3a is a soluble inflammatory mediator rather than the principal surface opsonin.'],['C5a','C5a strongly recruits and activates leukocytes rather than acting as the principal surface coat.'],['C9 monomer alone','C9 participates in pores rather than serving as the main phagocytic coat.']],
'C3 activation exposes reactive groups that permit C3b attachment to microbial surfaces. Phagocytes recognize bound complement through specific receptors, improving uptake. Soluble C3a and C5a instead promote inflammatory signaling, separating opsonization from recruitment and permeability effects.','Distinguish surface C3b opsonization from soluble complement inflammatory fragments.','terminal complement deficiency'),
q('Immunology','General Principles','C5a chemotactic gradient',2,'A bacterial focus generates a complement-derived gradient that strongly recruits neutrophils. Which soluble fragment is a particularly potent chemoattractant?',[
['C5a','C5a recruits and activates neutrophils through specific surface receptors.'],['C1q','C1q primarily recognizes initiating complexes rather than serving as this major gradient.'],['C9','C9 is a membrane attack complex component rather than a dominant soluble chemoattractant.'],['Intact C4 alone','Intact C4 is not the potent neutrophil chemoattractant described.']],
'Complement activation produces C5a, a powerful inflammatory and chemotactic signal. Neutrophils sense gradients through receptors and migrate toward the source. This recruitment function is distinct from C3b-mediated surface tagging and C5b-9 pore formation.','Identify C5a as a potent complement-derived neutrophil chemoattractant.','C3b opsonization'),
q('Immunology','General Principles','DAF host convertase restraint',2,'A normal host cell expresses a membrane protein that accelerates dissociation of complement convertases. Which protective protein performs this decay-accelerating role?',[
['CD55','CD55 limits complement activation by accelerating convertase decay.'],['CD28','CD28 supports T-cell costimulation rather than complement convertase decay.'],['CD3','CD3 transduces T-cell receptor signals rather than restraining surface convertases.'],['CD19','CD19 participates in B-cell signaling rather than serving as decay-accelerating factor.']],
'Host membranes display complement regulatory proteins to limit collateral injury. CD55, also called decay-accelerating factor, destabilizes convertases. Its function differs from CD59, which inhibits terminal membrane attack assembly, although both help protect host cells.','Identify CD55-mediated acceleration of complement convertase decay.','terminal complement deficiency'),
q('Immunology','General Principles','NK missing self recognition',2,'A virally infected cell reduces surface class I expression to evade cytotoxic T cells. Which innate lymphocyte can detect the resulting loss of inhibitory self signals?',[
['Natural killer cell','Reduced self class I can remove inhibitory NK receptor signaling.'],['Mature erythrocyte','Red cells are not cytotoxic lymphocytes with missing-self recognition.'],['Plasma cell','Plasma cells secrete antibodies rather than perform this innate cytotoxic sensing.'],['Resting eosinophil exclusively','Eosinophils do not provide the canonical class I missing-self pathway.']],
'NK cells integrate activating signals with inhibition supplied by self class I recognition. Loss of class I can reduce inhibition and permit killing when activating cues are sufficient. This provides a countermeasure against pathogens or tumors that evade class I-dependent T-cell recognition.','Explain NK surveillance of cells with reduced self class I display.','CD8 antigen recognition'),
q('Immunology','General Principles','ADCC Fc receptor recognition',2,'An antibody coats a tumor cell and an NK cell binds its Fc region before releasing cytotoxic granules. Which NK receptor commonly mediates this antibody-dependent recognition?',[
['CD16','CD16 binds IgG Fc and supports antibody-dependent cellular cytotoxicity.'],['CD4','CD4 is a class II-associated T-cell coreceptor rather than the NK IgG Fc receptor.'],['CD8','CD8 binds class I and does not perform the described IgG Fc recognition.'],['TAP','TAP is an intracellular peptide transporter rather than a surface Fc receptor.']],
'NK cells express CD16, an Fc receptor that recognizes IgG coating a target. Cross-linking activates cytotoxic granule release and target killing. Antibody provides specificity while the NK cell supplies the effector mechanism, distinguishing ADCC from direct complement-mediated lysis.','Identify CD16-mediated NK recognition during antibody-dependent cytotoxicity.','NK missing-self surveillance'),
q('Immunology','General Principles','Perforin granzyme killing',2,'A cytotoxic lymphocyte releases granules at a target-cell contact. Which granule enzyme enters the target and activates pathways leading to apoptosis?',[
['Granzyme','Granzymes enter target cells and initiate proteolytic apoptotic pathways.'],['Catalase','Catalase disposes of peroxide rather than acting as the principal cytotoxic granule protease.'],['Amylase','Amylase digests carbohydrate and does not trigger the described target-cell apoptosis.'],['Telomerase','Telomerase maintains chromosome ends rather than acting as a secreted cytotoxic protease.']],
'Cytotoxic lymphocytes release perforin and granzymes into a specialized contact. Perforin supports granzyme access to the target, where granzymes activate apoptotic pathways. Target death is therefore an organized intracellular response rather than simply indiscriminate extracellular digestion.','Distinguish granzyme apoptotic signaling from noncytotoxic enzyme functions.','generic apoptosis recognition'),
q('Immunology','General Principles','Fas activation-induced death',2,'After an immune response, an activated T cell receives a Fas ligand signal that recruits a death-inducing complex. Which upstream apoptosis route is engaged?',[
['Extrinsic death-receptor pathway','Fas recruits adaptor and initiator caspase machinery at a surface death receptor.'],['Only mitochondrial nutrient sensing','Fas signaling begins at a membrane death receptor rather than nutrient withdrawal.'],['Complement membrane pore formation','Fas-mediated apoptosis does not require a terminal complement pore.'],['Antibody class switching','Changing an immunoglobulin constant region does not initiate this T-cell death pathway.']],
'Fas is a death receptor that assembles an intracellular signaling complex after ligand binding. Initiator caspases activate downstream apoptotic machinery, helping remove activated lymphocytes. This receptor-triggered route is distinct from initiating apoptosis through mitochondrial growth-factor withdrawal.','Identify Fas-mediated initiation of extrinsic lymphocyte apoptosis.','growth-factor withdrawal intrinsic apoptosis'),
q('Immunology','General Principles','IL-2 autocrine expansion',2,'A recently activated T cell produces a cytokine and increases high-affinity receptors for it, promoting its own clonal proliferation. Which cytokine best fits this autocrine loop?',[
['Interleukin 2','IL-2 supports expansion of activated T cells and also regulatory T-cell maintenance.'],['Erythropoietin','Erythropoietin primarily stimulates erythroid production rather than this T-cell loop.'],['Thyroxine','Thyroxine is an endocrine metabolic hormone rather than the autocrine cytokine described.'],['Calcitonin','Calcitonin is not the principal cytokine driving activated T-cell clonal expansion.']],
'Antigen recognition and costimulation induce IL-2 production and high-affinity IL-2 receptor expression. The cytokine then supports proliferation of responsive lymphocytes through autocrine and paracrine signaling. This expansion follows activation rather than replacing the antigen recognition requirement.','Explain the IL-2 growth loop following productive T-cell activation.','CD28 costimulation'),
q('Immunology','General Principles','IL-12 Th1 polarization',2,'An antigen-presenting cell releases a cytokine that favors differentiation of naive helper T cells toward interferon-gamma-producing effectors. Which cytokine is most characteristic?',[
['Interleukin 12','IL-12 promotes Th1 differentiation and supports interferon-gamma responses.'],['Interleukin 4','IL-4 instead favors Th2 differentiation in the usual polarization framework.'],['Erythropoietin','This hormone supports erythroid cells rather than helper T-cell polarization.'],['Insulin','Insulin is not the antigen-presenting-cell cytokine driving Th1 differentiation.']],
'IL-12 from activated antigen-presenting cells promotes a Th1 program in responding helper T cells. These cells produce interferon-gamma and support responses against intracellular pathogens. The question concerns differentiation signals rather than the downstream macrophage-activating action of interferon-gamma.','Identify IL-12 as an upstream driver of Th1 polarization.','interferon-gamma granuloma maintenance'),
q('Immunology','General Principles','IL-4 Th2 polarization',2,'A naive helper T cell differentiates in an IL-4-rich environment and subsequently supports eosinophilic and IgE-associated responses. Which transcriptional helper program is favored?',[
['Th2 differentiation','IL-4 promotes the Th2 program associated with type 2 immune responses.'],['Th1 differentiation as the dominant direct effect','IL-12 and interferon-gamma rather than IL-4 favor the classic Th1 program.'],['Direct erythrocyte maturation','Helper T-cell polarization does not transform the cell into an erythrocyte.'],['Loss of all adaptive specificity','Polarization alters effector function without abolishing antigen receptor specificity.']],
'IL-4 supports differentiation toward Th2 cells, which produce cytokines participating in type 2 responses. These responses can support parasite defense and allergic inflammation. Polarization determines effector behavior while the rearranged antigen receptor retains its recognition specificity.','Connect IL-4 exposure with helper T-cell type 2 differentiation.','IgE mast-cell degranulation'),
q('Immunology','General Principles','IL-17 barrier neutrophil recruitment',2,'A mucosal T-cell response induces epithelial chemokines that recruit neutrophils against extracellular organisms. Which helper-cell cytokine is particularly associated with this response?',[
['Interleukin 17','IL-17 promotes tissue chemokine and growth-factor responses supporting neutrophils.'],['Interleukin 4 alone','IL-4 chiefly supports type 2 differentiation rather than this neutrophil program.'],['Erythropoietin','Erythropoietin supports erythropoiesis rather than barrier neutrophil recruitment.'],['Melatonin','Melatonin conveys circadian information rather than the specific helper-cell effector signal.']],
'Th17-associated IL-17 acts on epithelial and stromal cells to stimulate mediators supporting neutrophil recruitment and production. This helps defend barriers against selected extracellular bacteria and fungi. It differs from direct antibody neutralization or Th2-driven eosinophilic responses.','Associate IL-17 with barrier-driven neutrophil recruitment.','C5a immediate chemotaxis'),
q('Immunology','General Principles','FOXP3 regulatory lineage',1,'A lymphocyte population expresses CD4, high CD25, and the transcription factor FOXP3 and restrains immune activation. Which lineage is most characteristic?',[
['Regulatory T cells','FOXP3 is a defining regulator of the canonical regulatory T-cell program.'],['Mature plasma cells','Plasma cells specialize in antibody secretion rather than the FOXP3 program.'],['Neutrophils','Neutrophils do not comprise this CD4-positive regulatory lymphocyte lineage.'],['Natural killer cells','NK cells use a different developmental and recognition program.']],
'FOXP3 supports the development and suppressive functions of canonical regulatory T cells. These cells help maintain peripheral tolerance and constrain excessive responses. High CD25 expression supports IL-2 responsiveness but should be interpreted with the complete phenotype rather than alone.','Identify the FOXP3-associated regulatory T-cell lineage.','thymic negative selection'),
q('Immunology','General Principles','IL-10 inflammatory restraint',2,'A macrophage exposed to a regulatory cytokine decreases production of several inflammatory mediators and its ability to stimulate T cells. Which cytokine best fits?',[
['Interleukin 10','IL-10 restrains many macrophage and antigen-presenting-cell inflammatory functions.'],['Interferon gamma','Interferon-gamma generally enhances classical macrophage activation.'],['Interleukin 12','IL-12 supports type 1 responses rather than this principal suppressive effect.'],['Granulocyte colony-stimulating factor exclusively','G-CSF principally supports granulocyte production rather than defining this suppression.']],
'IL-10 acts on macrophages and other antigen-presenting cells to limit inflammatory cytokine output and stimulatory activity. This helps regulate immune response intensity. The effect contrasts with interferon-gamma-driven activation and does not imply elimination of every host defense function.','Explain IL-10-mediated restraint of inflammatory antigen-presenting cells.','Th1 macrophage activation'),
q('Immunology','General Principles','Superantigen external crosslinking',3,'A bacterial protein causes broad T-cell activation without conventional peptide processing and binds outside the usual peptide-specific recognition site. Which mechanism explains this?',[
['Crosslinking class II and selected TCR V-beta regions','Superantigens activate many T cells sharing susceptible V-beta families.'],['Precise binding to one unique processed peptide clone','The broad response is not limited to one conventional peptide-specific clone.'],['Destruction of every T-cell receptor gene','The acute response requires receptor engagement rather than deletion of all receptor genes.'],['Direct neutralization of all inflammatory cytokines','The protein causes activation rather than cytokine neutralization.']],
'Superantigens bind class II molecules and T-cell receptor V-beta regions outside ordinary peptide-specific contacts. This recruits a much broader T-cell population than conventional antigen presentation and can cause intense cytokine release. Lack of usual processing and broad activation identify the mechanism together.','Integrate processing independence and broad T-cell activation to identify superantigen action.','ordinary class II antigen presentation'),
q('Immunology','General Principles','T-independent repetitive epitopes',2,'A highly repetitive bacterial polysaccharide activates B cells without conventional protein-specific T-cell help. Which property helps produce this T-independent response?',[
['Extensive crosslinking of B-cell receptors','Repeated epitopes engage multiple receptors and can strongly stimulate appropriate B cells.'],['Presentation of polysaccharide peptides on class II','Pure polysaccharide does not become a conventional peptide antigen by this route.'],['Direct conversion of B cells into helper T cells','T-independent activation does not require lineage conversion.'],['Elimination of all innate accessory signals','T-independent responses can still depend on innate signals and cellular context.']],
'Repetitive polysaccharide arrays can crosslink many B-cell receptors and activate selected B-cell populations with limited conventional T-cell help. These responses generally have less robust memory and affinity maturation than protein-linked responses. T-independent does not mean independent of every accessory signal.','Explain B-cell receptor crosslinking by repetitive T-independent polysaccharides.','protein-dependent class switching'),
q('Immunology','General Principles','Conjugate vaccine linked recognition',3,'A B cell binds a capsule polysaccharide linked to a carrier protein, internalizes the conjugate, and receives carrier-specific T-cell help. Why does linkage improve the response?',[
['The B cell presents carrier peptides after capturing its target polysaccharide','Linked recognition supplies T-cell help to the polysaccharide-specific B cell.'],['The carrier turns polysaccharide into a peptide chemically','The carbohydrate remains carbohydrate; carrier protein provides presentable peptides.'],['All T cells directly recognize free polysaccharide on class I','Conventional helper recognition uses carrier peptides with class II.'],['The conjugate removes the need for antigen-specific B cells','Specific B-cell capture remains central to the linked response.']],
'A polysaccharide-specific B cell captures the linked conjugate through its receptor and presents carrier-derived peptides on class II. Carrier-specific helper cells can then provide cognate help to that B cell. Physical linkage coordinates antigen capture and peptide presentation, supporting stronger memory and maturation.','Explain linked recognition in a polysaccharide-protein conjugate response.','T-independent polysaccharide activation'),
q('Immunology','General Principles','RAG recombination initiation',2,'Early lymphoid cells cannot make the programmed DNA cuts needed to assemble antigen receptor variable regions. Which enzyme complex normally initiates this rearrangement?',[
['RAG1-RAG2','RAG proteins recognize recombination signals and initiate V(D)J rearrangement.'],['Telomerase','Telomerase extends chromosome ends rather than initiating antigen receptor gene assembly.'],['Catalase','Catalase detoxifies peroxide rather than rearranging lymphocyte receptor DNA.'],['Enteropeptidase','Enteropeptidase activates intestinal trypsinogen rather than receptor genes.']],
'RAG1 and RAG2 recognize recombination signal sequences and initiate breaks for V(D)J recombination. Joining selected variable, diversity, and joining segments generates antigen receptor diversity in developing B and T cells. This occurs before antigen-driven somatic hypermutation of mature B cells.','Identify RAG initiation of antigen receptor V(D)J recombination.','class switching and affinity maturation'),
q('Immunology','General Principles','TdT junctional diversity',2,'During antigen receptor assembly, nucleotides not encoded by the adjacent gene segments are added at joining sites. Which enzyme produces this source of diversity?',[
['Terminal deoxynucleotidyl transferase','TdT adds non-templated nucleotides during receptor gene joining.'],['DNA helicase alone','Helicase unwinds DNA rather than specifically adding non-templated junctional bases.'],['RNA polymerase I','This enzyme transcribes ribosomal RNA rather than creating receptor joining diversity.'],['Pyruvate kinase','This metabolic enzyme does not catalyze receptor DNA junctional changes.']],
'TdT adds nucleotides without a DNA template at coding joins during V(D)J recombination. Together with trimming and segment choice, this creates highly diverse antigen-binding regions. Junctional addition is a developmental DNA assembly process rather than later protein glycosylation.','Identify TdT-generated non-templated receptor junctional diversity.','RAG cleavage initiation'),
q('Immunology','General Principles','Immunoglobulin allelic exclusion',2,'A developing B cell successfully rearranges one heavy-chain allele and suppresses productive rearrangement of the second. What is the principal functional result?',[
['One dominant antigen receptor specificity per B cell','Allelic exclusion helps maintain coherent clonal receptor specificity.'],['Expression of every possible antibody in one cell','The process restricts rather than maximizes receptor diversity within a single cell.'],['Loss of all population-level antibody diversity','Different clones retain distinct rearrangements across the population.'],['Automatic switching to every constant-region isotype','Heavy-chain allelic exclusion is distinct from later isotype switching.']],
'A successful receptor rearrangement generates feedback limiting additional productive rearrangements. This allelic exclusion supports a single dominant receptor specificity in an individual B-cell clone. Diversity remains extensive across clones, allowing clonal selection while preserving a coherent response within each clone.','Explain allelic exclusion as support for B-cell clonal specificity.','immunoglobulin class switching'),
q('Immunology','General Principles','HLA codominant expression',1,'A nucleated cell in a person heterozygous at an HLA locus displays products encoded by both inherited alleles. Which genetic expression pattern is demonstrated?',[
['Codominant expression','Both parental HLA alleles contribute expressed surface products.'],['Complete paternal silencing at every HLA locus','Ordinary HLA expression is not universal paternal imprinting.'],['X-linked inactivation','HLA loci are not regulated by random X-chromosome inactivation.'],['Recessive nonexpression of both alleles','The stem explicitly describes expression from both alleles.']],
'HLA alleles are generally expressed codominantly, so both maternally and paternally inherited products contribute to antigen presentation. Heterozygosity can broaden the peptide repertoire displayed. This expression pattern differs from dominance of a single allele or parent-of-origin silencing.','Recognize codominant expression of inherited HLA alleles.','genomic imprinting'),
q('Immunology','General Principles','Alternative complement properdin',2,'A complement convertase assembled on a microbial surface decays more rapidly when a stabilizing plasma protein is absent. Which protein normally stabilizes the alternative-pathway convertase?',[
['Properdin','Properdin stabilizes the alternative-pathway C3 convertase.'],['CD55','CD55 promotes convertase decay rather than stabilizing it.'],['Albumin','Albumin is not the specific stabilizer of the alternative convertase.'],['IgE','IgE does not serve as the principal structural stabilizer of this convertase.']],
'The alternative pathway builds a C3 convertase from surface-associated C3b and factor B-derived components. Properdin stabilizes this otherwise labile complex, supporting amplification. Its promoting role contrasts with host regulators such as CD55, which accelerate convertase decay.','Identify properdin stabilization of the alternative complement convertase.','terminal complement deficiency'),
q('Immunology','General Principles','Lectin complement carbohydrate recognition',2,'Complement activation begins when a soluble host lectin binds repeating microbial carbohydrates without antibody. Which initiator is characteristic of this pathway?',[
['Mannose-binding lectin','MBL recognizes microbial carbohydrate patterns and activates associated proteases.'],['C1q bound to IgG','That describes antibody-associated classical pathway initiation rather than lectin recognition.'],['T-cell receptor alpha chain','A membrane T-cell receptor does not initiate this soluble lectin pathway.'],['Perforin','Perforin participates in lymphocyte cytotoxicity rather than complement initiation.']],
'Mannose-binding lectin recognizes suitable carbohydrate arrays on microbial surfaces. Associated serine proteases initiate a cascade sharing downstream components with the classical pathway. Antibody is unnecessary for this recognition event, distinguishing the lectin pathway from antibody-triggered C1 activation.','Identify antibody-independent carbohydrate recognition by the lectin complement pathway.','classical C1q initiation'),
q('Immunology','General Principles','Type I interferon antiviral state',2,'A virally infected cell releases interferon-alpha and interferon-beta. Neighboring uninfected cells increase proteins that impede viral replication. Which response is demonstrated?',[
['Induction of an antiviral state','Type I interferons alter gene expression to limit viral replication in nearby cells.'],['Direct antibody isotype switching alone','The described immediate neighboring-cell response is not limited to B-cell isotype change.'],['Conversion of host cells into viruses','Interferon signaling protects host cells rather than creating viral particles.'],['Guaranteed sterilizing immunity against every virus','Antiviral signaling reduces susceptibility but does not guarantee universal protection.']],
'Type I interferons bind receptors on surrounding cells and induce antiviral gene programs. These can inhibit viral protein production and nucleic acid replication, limiting spread before antigen-specific immunity is fully established. They are protective signals rather than antibodies or a guarantee of complete clearance.','Explain paracrine induction of a type I interferon antiviral program.','HIV receptor entry'),
q('Immunology','General Principles','Pattern recognition conserved motifs',1,'A macrophage receptor recognizes a conserved microbial molecular pattern shared by many organisms without prior rearrangement of its receptor gene. Which receptor category is involved?',[
['Pattern-recognition receptor','Germline-encoded receptors detect conserved microbial or damage-associated patterns.'],['Somatically rearranged immunoglobulin only','The stated receptor does not require antigen receptor gene rearrangement.'],['Individual clone-specific T-cell receptor','T-cell receptors are generated through somatic rearrangement rather than this fixed pattern system.'],['Nuclear thyroid hormone receptor','This endocrine receptor does not fit the described microbial pattern recognition.']],
'Innate pattern-recognition receptors are encoded in the germline and detect conserved molecular features. They initiate cellular signaling without requiring prior clonal selection or receptor rearrangement. This contrasts with the immense somatic diversity of B-cell and T-cell antigen receptors.','Distinguish germline innate pattern recognition from rearranged adaptive receptors.','B-cell receptor diversity'),
q('Immunology','General Principles','Inflammasome IL-1beta maturation',2,'A macrophage assembles an inflammasome after detecting cellular danger. Which protease directly processes pro-interleukin-1beta into its mature inflammatory form?',[
['Caspase 1','Inflammasome activation drives caspase-1 cleavage of pro-inflammatory cytokine precursors.'],['Pepsin','Pepsin is a gastric digestive protease rather than the inflammasome effector.'],['Thrombin','Thrombin acts principally in coagulation rather than this intracellular cytokine maturation step.'],['Trypsin','Trypsin is not the canonical macrophage inflammasome cytokine-processing protease.']],
'Inflammasomes are intracellular signaling assemblies that activate inflammatory caspases, especially caspase-1 in canonical pathways. Caspase-1 cleaves pro-IL-1beta and pro-IL-18 into mature forms. This proteolytic maturation differs from simply transcribing a cytokine gene or secreting an unchanged precursor.','Identify caspase-1-dependent cytokine maturation downstream of an inflammasome.','apoptotic executioner caspases'),
q('Immunology','General Principles','Eosinophil granule helminth injury',2,'A large helminth cannot be engulfed by one leukocyte. Eosinophils attach and release granule proteins onto its surface. Which granule constituent contributes to this extracellular injury?',[
['Major basic protein','Eosinophil major basic protein can damage large parasite surfaces and host tissues.'],['Hemoglobin A','Hemoglobin is not a major eosinophil cytotoxic granule constituent.'],['Intrinsic factor','This gastric protein binds B12 rather than damaging helminths.'],['Albumin','Albumin maintains oncotic pressure rather than serving as the characteristic granule toxin.']],
'Eosinophils can release toxic granule contents against targets too large for ordinary phagocytosis. Major basic protein is one such constituent and can also injure host tissue during allergic inflammation. The extracellular effector strategy differs from neutrophil uptake of small bacteria.','Associate eosinophil major basic protein with extracellular helminth-directed injury.','IgE-mediated immediate allergy'),
q('Genetics','General Principles','Missense amino acid substitution',1,'A single-base substitution changes one protein codon so that a different amino acid is inserted, without changing protein length. Which variant type is this?',[
['Missense variant','A missense substitution changes the encoded amino acid at one position.'],['Nonsense variant','A nonsense substitution introduces a premature termination codon.'],['Frameshift variant','A frameshift changes downstream reading frame rather than one codon alone.'],['Whole-gene deletion','Deleting an entire gene is not the single-codon change described.']],
'A missense variant replaces an amino-acid codon with another amino-acid codon. Its effect depends on the residue and protein context; it is not automatically pathogenic. Unlike a nonsense variant, it does not itself introduce an early stop, and it need not change protein length.','Identify a missense variant from a single amino-acid replacement.','inheritance pattern recognition'),
q('Genetics','General Principles','Nonsense premature stop',1,'A base substitution converts a coding triplet into a termination codon well before the normal protein end. Which sequence-level variant classification applies?',[
['Nonsense variant','The substitution creates a premature stop rather than encoding an amino acid.'],['Synonymous variant','A synonymous change preserves the encoded amino acid rather than creating a stop.'],['In-frame duplication','The stem describes one substituted base rather than repeated coding sequence.'],['Balanced translocation','A chromosome rearrangement is not needed to explain this codon substitution.']],
'Nonsense variants create premature termination codons. They can yield truncated protein or trigger degradation of the transcript, depending on position and context. The classification describes the sequence change and does not alone establish the amount of remaining protein or clinical severity.','Recognize a nonsense substitution that introduces premature translation termination.','missense substitution'),
q('Genetics','General Principles','Coding frameshift deletion',2,'A coding exon loses one nucleotide and all subsequent triplets are regrouped until a new stop appears. Which consequence best describes this deletion?',[
['Frameshift','A non-triplet coding deletion changes the downstream reading frame.'],['Only one amino acid must be missing','Removing one base changes triplet grouping rather than simply deleting one residue.'],['No protein sequence effect is possible','The stated coding deletion directly alters downstream translation.'],['Whole chromosome nondisjunction','A small exon deletion does not require chromosome segregation failure.']],
'Coding sequence is read in groups of three nucleotides. A one-base deletion shifts grouping of downstream bases, often producing multiple altered amino acids and a premature stop. The effect differs from deletion of an exact multiple of three bases, which can preserve the reading frame.','Apply triplet coding to explain a non-triplet deletion frameshift.','nondisjunction'),
q('Genetics','General Principles','In-frame coding deletion',2,'A gene loses six coding nucleotides entirely within an exon, with no splice-site disruption. Which protein consequence is most directly predicted from the sequence alone?',[
['Loss of two amino acids with downstream frame preserved','A six-base deletion removes two codons without changing the remaining triplet phase.'],['An obligatory downstream frameshift','Deleting a multiple of three bases can preserve the reading frame.'],['Guaranteed absence of any functional effect','An in-frame deletion can still disrupt an important protein region.'],['A new whole chromosome','A small coding deletion does not create an additional chromosome.']],
'A deletion in a multiple of three bases can remove complete codons while preserving downstream reading frame. Two residues are lost here, but functional impact depends on their role and the surrounding structure. Frame preservation therefore does not establish benignity.','Distinguish in-frame codon loss from a downstream reading-frame shift.','frameshift mechanism'),
q('Genetics','General Principles','Splice donor disruption',2,'A variant alters the conserved donor sequence at an exon-intron boundary. The mature RNA retains intronic sequence. Which molecular process is most directly disrupted?',[
['Pre-mRNA splicing','Splice-site recognition normally removes introns and joins coding exons.'],['Translation termination at the normal stop only','The primary defect is RNA processing rather than recognition of an unchanged stop.'],['Mitochondrial membrane pumping','Membrane transport does not explain nuclear transcript intron retention.'],['DNA segregation during anaphase','Chromosome segregation does not directly remove pre-mRNA introns.']],
'Splice donor sequences help the spliceosome recognize exon-intron boundaries. Their disruption can cause intron retention, exon skipping, or use of a cryptic site. The resulting transcript may encode altered protein even when no ordinary amino-acid codon was initially changed.','Link a donor-site variant with abnormal removal of pre-mRNA introns.','alternative physiological splicing'),
q('Genetics','General Principles','Promoter expression reduction',2,'A variant lies upstream of the coding region and reduces transcription-factor binding. Protein sequence remains normal but protein abundance falls. Which mechanism best explains this?',[
['Reduced transcription initiation','A promoter alteration can lower transcript production without changing protein sequence.'],['Obligatory missense substitution','A noncoding upstream variant need not alter any amino-acid codon.'],['Universal failure of translation elongation','The specific evidence points to reduced transcription rather than all elongation failure.'],['Increased gene copy number as the only mechanism','The stated reduction follows impaired binding rather than additional gene copies.']],
'Promoter elements regulate recruitment and activity of transcription machinery. A variant that weakens an activating interaction can reduce messenger RNA production and thus protein amount. Because the coding region remains unchanged, the translated molecules may have a normal amino-acid sequence.','Explain lower protein abundance from impaired promoter activity.','coding missense changes'),
q('Genetics','General Principles','Synonymous splice regulatory effect',3,'A coding substitution preserves the amino acid but disrupts an exonic splicing enhancer. RNA analysis shows exon skipping. Which interpretation best integrates these observations?',[
['A synonymous coding change can still alter RNA processing','Preserving one codon meaning does not preserve every regulatory function of the sequence.'],['Every synonymous variant is necessarily harmless','The demonstrated splicing effect contradicts a universal harmlessness rule.'],['The protein codon must encode a new amino acid directly','The codon is synonymous; the separate splicing effect changes the transcript.'],['RNA findings cannot be influenced by DNA sequence','Splice regulation depends partly on DNA-encoded transcript sequences.']],
'A synonymous variant preserves the directly encoded amino acid but may alter splice regulatory motifs, RNA stability, or translation behavior. Demonstrated exon skipping supplies a functional mechanism beyond the codon label. Sequence classification alone therefore cannot establish benignity.','Integrate synonymous codon preservation with disrupted splicing regulation.','splice donor disruption'),
q('Genetics','General Principles','Nonsense-mediated transcript decay',2,'A premature stop codon lies sufficiently upstream of a remaining exon junction, and the mutant transcript becomes scarce. Which surveillance mechanism can explain the reduced RNA?',[
['Nonsense-mediated mRNA decay','Surveillance can recognize premature termination and promote transcript degradation.'],['Obligatory chromosome loss','Selective transcript depletion does not require loss of the entire chromosome.'],['Conversion of messenger RNA into collagen','RNA surveillance does not convert the transcript into matrix protein.'],['Normal poly-A extension as the sole explanation','Tail addition alone does not explain selective recognition of a premature stop.']],
'Nonsense-mediated decay limits production of potentially harmful truncated proteins by degrading certain transcripts with premature stops. Exon-junction context influences recognition, so not every nonsense variant has the same RNA consequence. Scarce mutant RNA can therefore reflect surveillance rather than reduced transcription alone.','Explain context-dependent degradation of a premature-stop transcript.','nonsense variant classification'),
q('Genetics','General Principles','Haploinsufficient dosage mechanism',2,'A person has one inactive allele of a dosage-sensitive gene. The remaining allele produces normal protein, but half the usual amount is insufficient for normal function. What mechanism applies?',[
['Haploinsufficiency','One functional copy cannot provide enough product to maintain the normal phenotype.'],['Dominant-negative interference','No mutant protein poisoning of a normal complex is described.'],['Gain of normal protein abundance','The key finding is reduced dosage rather than excess protein.'],['Complete mitochondrial inheritance','The mechanism concerns dosage at a diploid gene rather than maternal organelle transmission.']],
'Haploinsufficiency occurs when one functional allele supplies too little gene product for normal function. Disease can therefore follow heterozygous loss of function without a toxic mutant protein. This differs from dominant-negative action, which requires interference by the altered product.','Distinguish insufficient normal dosage from mutant-protein interference.','tumor suppressor two-hit model'),
q('Genetics','General Principles','Dominant negative multimer poisoning',3,'A mutant subunit enters a multimeric protein and disrupts complexes containing normal subunits. Function is lower than predicted from simple loss of one allele. Which mechanism fits?',[
['Dominant-negative interference','The altered product impairs function of complexes that include normal protein.'],['Simple haploinsufficiency alone','The experiment demonstrates active interference beyond reduced product dosage.'],['Silent codon substitution without functional consequence','The measured disruption establishes a functional effect.'],['Loss of every mitochondrial genome','The described multimer interference does not require organelle genome elimination.']],
'A dominant-negative protein retains interactions needed to enter a complex but compromises its function. Mutant subunits can therefore disable assemblies containing wild-type partners. The combination of preserved assembly and disproportionately low function distinguishes interference from simply producing less normal protein.','Infer dominant-negative action from mutant incorporation and impaired mixed complexes.','haploinsufficient gene dosage'),
q('Genetics','General Principles','Constitutive receptor gain of function',2,'A receptor variant produces signaling even when no ligand is present, while the other allele is normal. Which functional class best describes this molecular change?',[
['Gain of function','The variant creates excessive or constitutive activity beyond normal ligand control.'],['Complete absence of receptor synthesis','A receptor that signals constitutively must be present and active.'],['Only loss of gene dosage','The defining effect is added activity rather than insufficient normal product.'],['Recessive transcript silence in every cell','The mutant product is active rather than universally transcriptionally silent.']],
'Gain-of-function variants can increase activity, produce constitutive signaling, or confer a new function. A ligand-independent receptor continues downstream signaling despite the absence of its normal trigger. This differs mechanistically from dosage reduction or a nonfunctional receptor allele.','Classify ligand-independent receptor signaling as gain of function.','tumor suppressor loss'),
q('Genetics','General Principles','Allelic heterogeneity',1,'Different families have the same single-gene disorder, but sequencing identifies distinct pathogenic variants in the same gene. Which term describes this pattern?',[
['Allelic heterogeneity','Different disease-causing variants at one locus can produce a similar disorder.'],['Locus heterogeneity','Locus heterogeneity involves different genes rather than different variants in one gene.'],['Complete nonpenetrance','The stem concerns variant diversity rather than absence of a phenotype.'],['Uniparental disomy','Inheritance of two homologues from one parent does not define this pattern.']],
'Allelic heterogeneity means that distinct pathogenic variants within one gene can lead to a related phenotype. The variants need not disrupt the protein in exactly the same way. This differs from locus heterogeneity, in which changes in different genes produce overlapping clinical disorders.','Distinguish multiple causal variants in one gene as allelic heterogeneity.','penetrance'),
q('Genetics','General Principles','Locus heterogeneity',1,'Two unrelated families have a similar inherited hearing phenotype, but the causal variants occur in different genes. Which term describes this genetic pattern?',[
['Locus heterogeneity','Variants in different genes can converge on a similar phenotype.'],['Allelic heterogeneity alone','That term refers to different variants within the same gene.'],['Aneuploidy in every family','Different causal genes do not require abnormal chromosome number.'],['Genomic imprinting alone','Parent-of-origin expression does not define different genes causing similar disease.']],
'Locus heterogeneity occurs when variants in distinct genes lead to similar phenotypes, often because their products participate in a shared pathway. A recognizable phenotype therefore does not always identify one gene. Allelic heterogeneity instead refers to variant diversity within one locus.','Recognize different causal genes producing an overlapping phenotype.','allelic heterogeneity'),
q('Genetics','General Principles','Variable expressivity severity',2,'Several relatives with the same pathogenic variant all show disease features, but one is mildly affected and another has severe multisystem findings. Which term describes this difference?',[
['Variable expressivity','Affected carriers can differ in the type or severity of manifestations.'],['Reduced penetrance as the demonstrated feature','Every carrier described is affected; the difference is severity rather than presence.'],['A new chromosome count in every relative','Variable phenotype does not require different chromosome numbers.'],['Absence of any genetic contribution','Shared causal variation remains compatible with variable manifestations.']],
'Expressivity describes the nature and severity of phenotype among affected individuals. Modifier genes, environment, and other factors can produce variability despite the same causal variant. Penetrance instead asks whether a carrier manifests the phenotype at all, making it a different dimension.','Distinguish variable disease severity from incomplete penetrance.','penetrance in unaffected carriers'),
q('Genetics','General Principles','Gonadal mosaic recurrence',3,'Two siblings share a pathogenic variant absent from both parents blood samples. Biological parentage is confirmed and the disorder is otherwise usually dominant. Which mechanism can explain recurrence?',[
['Parental germline mosaicism','A subset of parental gametes can carry a variant absent from sampled blood cells.'],['Proof that the variant is noncausal','Absence in parental blood does not exclude a causal transmitted gametic variant.'],['Mandatory identical independent mutations in every body cell','Recurrence does not require new mutations throughout all parental tissues.'],['Normal blood results exclude all reproductive risk','A blood sample does not exhaustively test every parental germ cell.']],
'A postzygotic variant in a parent can involve some germ cells while being absent or undetectable in blood. More than one gamete can therefore transmit the same variant. Confirmed sibling recurrence and negative parental blood testing together support consideration of germline mosaicism.','Integrate recurrence and negative parental blood testing as evidence compatible with gonadal mosaicism.','autosomal dominant transmission'),
q('Genetics','General Principles','Postzygotic somatic mosaicism',2,'A skin variant is present in one patch but absent from adjacent skin and blood. The cells originated from the same fertilized egg. Which mechanism best explains this distribution?',[
['A postzygotic variant in one cell lineage','A change after fertilization can produce genetically distinct descendant cell populations.'],['Two different maternal alleles in every cell','The restricted patch does not require a constitutional difference in all tissues.'],['Mandatory fusion of two embryos','Mosaicism from one zygote differs from chimerism involving distinct zygotes.'],['A variant present in every gamete of both parents','A universal transmitted variant would not explain this restricted somatic distribution.']],
'A mutation after fertilization can be inherited by only the descendants of the affected cell. Tissue lineage and developmental timing determine the resulting mosaic distribution. A patch-specific variant can therefore be absent from blood, unlike a constitutional variant present throughout sampled tissues.','Infer somatic mosaicism from a lineage-restricted postzygotic variant.','germline mosaic recurrence'),
q('Genetics','General Principles','Skewed X-inactivation expression',3,'A heterozygous woman has unexpectedly marked manifestations of an X-linked disorder. In the relevant tissue, most cells silence the X carrying the normal allele. Which mechanism explains the severity?',[
['Skewed X-chromosome inactivation','Preferential silencing of the normal allele leaves the pathogenic allele active in more cells.'],['Universal activation of both X chromosomes','The evidence describes preferential inactivation rather than two active copies.'],['Y-linked inheritance','The variant is X-linked and the patient does not need a Y-linked explanation.'],['Loss of all autosomal chromosomes','The tissue-specific allele expression does not imply autosomal chromosome loss.']],
'X inactivation creates cellular mosaicism for expression of X-linked genes subject to silencing. Strong skewing toward the normal allele being inactive increases the fraction expressing the pathogenic allele. Genotype alone therefore may not predict severity without considering tissue expression patterns.','Integrate genotype and tissue X-inactivation bias to explain an X-linked phenotype.','X-linked recessive transmission probability'),
q('Genetics','General Principles','Mitochondrial heteroplasmy threshold',3,'Two tissues contain the same mitochondrial variant but differ markedly in mutant genome proportion. Only the tissue with high mutant burden has impaired energy production. What explains this?',[
['A tissue-dependent heteroplasmy threshold','Functional impairment can emerge when mutant load exceeds a tissue-specific tolerance.'],['Every mitochondrial variant has identical effects at all burdens','The observed difference contradicts burden-independent function.'],['Ordinary paternal X inactivation','Mitochondrial genome proportions are not regulated by X-chromosome inactivation.'],['A requirement that all mitochondrial genomes be mutant','Disease can occur before every mitochondrial genome carries the variant.']],
'Heteroplasmy is coexistence of normal and variant mitochondrial genomes. The functional impact depends on mutant proportion and tissue energy requirements, with threshold behavior often observed. Different tissues can therefore be affected unequally despite carrying the same underlying variant.','Explain tissue-selective dysfunction through heteroplasmy and energetic thresholds.','maternal mitochondrial inheritance'),
q('Genetics','General Principles','Microarray copy number detection',2,'A child has a small chromosomal deletion below routine karyotype resolution. Which genomic test is designed to detect submicroscopic gains or losses across many loci?',[
['Chromosomal microarray','Array-based dosage analysis can identify submicroscopic copy-number changes.'],['A single serum protein measurement','Protein concentration does not directly map genome-wide DNA dosage.'],['Routine bacterial culture','Microbial culture does not detect a human chromosomal microdeletion.'],['Direct muscle strength examination alone','Examination may reveal phenotype but does not measure genomic copy number.']],
'Chromosomal microarrays compare DNA signals across many genomic regions to detect copy-number imbalance. They can find deletions too small for routine banded karyotyping. A normal array does not exclude all sequence variants or balanced rearrangements, because dosage and sequence are different measurements.','Select genomic dosage analysis for a submicroscopic chromosomal deletion.','balanced translocation'),
q('Genetics','General Principles','Balanced rearrangement array limitation',3,'A person has a balanced reciprocal translocation on karyotype but a normal copy-number microarray. Why are these results compatible rather than necessarily contradictory?',[
['The array measures dosage and may miss copy-neutral rearrangement','Relocating DNA can preserve the total amount detected by a dosage assay.'],['Every translocation must delete a full chromosome','Balanced exchange can retain total genetic material.'],['Microarray directly visualizes every chromosome junction','Dosage arrays do not comprehensively map all balanced breakpoints.'],['Karyotypes cannot detect any structural rearrangements','Visible chromosomal exchanges can be identified by cytogenetic analysis.']],
'A balanced translocation exchanges chromosomal material without a net dosage change detectable by a copy-number assay. Karyotype and microarray interrogate different properties, so both findings can be correct. A balanced label also does not prove every breakpoint is functionally harmless.','Reconcile a visible balanced translocation with normal genomic copy-number results.','balanced translocation reproductive risk'),
q('Genetics','General Principles','FISH targeted localization',2,'A laboratory uses a fluorescent DNA probe complementary to one suspected chromosomal locus. Which method directly visualizes where that targeted sequence is located?',[
['Fluorescence in situ hybridization','FISH probes hybridize to selected sequences in cells or chromosomes.'],['Serum electrophoresis','This separates circulating proteins rather than localizing a specific chromosomal DNA target.'],['Gram staining','Gram staining categorizes bacterial cell-wall behavior rather than human DNA loci.'],['Western blot alone','A Western blot detects proteins rather than directly visualizing a DNA sequence location.']],
'FISH uses labeled nucleic acid probes to hybridize with complementary chromosomal targets. It can address specific questions about location or copy number depending on probe design. Because it is targeted, a normal result does not survey every region or exclude unrelated genomic changes.','Identify targeted fluorescent DNA localization as FISH.','genome-wide microarray dosage'),
q('Genetics','General Principles','PCR primer site allele dropout',3,'A heterozygous variant appears homozygous after PCR, but an independent method detects both alleles. A nearby change lies beneath one primer. Which artifact best explains the discrepancy?',[
['Allele dropout from impaired primer binding','One allele may amplify poorly when its primer-binding sequence differs.'],['Proof of whole-chromosome loss in all tissues','Independent detection of both alleles argues against this universal conclusion.'],['Normal conversion of one allele into the other during PCR','Routine amplification does not intentionally replace one inherited allele with another.'],['Guaranteed sample contamination','The primer-site change offers a specific alternative technical explanation.']],
'PCR depends on primer binding to both target alleles. A variant beneath a primer can reduce amplification of one allele, making a heterozygous sample appear homozygous. Independent methods and redesigned primers can resolve this discrepancy; the initial trace alone does not establish true homozygosity.','Infer primer-related allele dropout from discordant genotypes and a primer-site variant.','sequence variant classification'),
q('Genetics','General Principles','Sanger dideoxy termination',1,'A sequencing reaction includes labeled nucleotides lacking a three-prime hydroxyl group. Their incorporation produces fragments of different lengths. Which principle is used?',[
['Dideoxy chain termination','Without a three-prime hydroxyl, the growing DNA strand cannot be extended normally.'],['RNA intron splicing','The reaction concerns DNA synthesis rather than removal of RNA introns.'],['Protein peptide cleavage','The fragments are DNA rather than peptides cut by proteases.'],['Chromosome centromere separation','Sequencing fragments do not arise from mitotic centromere division.']],
'DNA polymerization requires a three-prime hydroxyl on the terminal nucleotide. A dideoxynucleotide lacks this group and terminates extension when incorporated. Separating labeled fragments by length allows the sequence to be inferred from their terminal bases.','Explain Sanger sequencing through dideoxynucleotide chain termination.','DNA polymerase directionality'),
q('Genetics','General Principles','Low-level mosaic sequencing depth',3,'A blood specimen contains a pathogenic variant in only a small minority of cells. A routine sequencing assay is negative. Which limitation must be considered before excluding mosaicism?',[
['Insufficient assay sensitivity for a low variant fraction','Sparse coverage or filtering can miss a variant present in few sampled molecules.'],['Every negative sequence assay proves every tissue is normal','Sampling and assay sensitivity limit that universal conclusion.'],['A low cell fraction must make the variant biologically impossible','Mosaic variants can exist in small fractions of sampled cells.'],['More sequencing always reveals the exact clinical outcome','Better detection does not by itself establish tissue distribution or phenotype severity.']],
'Detection of mosaicism depends on variant fraction, sampled tissue, read depth, and validated analytical thresholds. A negative routine assay may not exclude a low-level variant. The result must be interpreted within its detection limits rather than generalized to every cell and tissue.','Integrate low variant fraction and assay sensitivity when interpreting negative sequencing.','somatic mosaic tissue distribution'),
q('Genetics','General Principles','Variant uncertain significance interpretation',2,'Sequencing finds a rare missense variant, but segregation and functional evidence are insufficient. Which interpretation best reflects a variant of uncertain significance?',[
['Available evidence does not establish pathogenicity or benignity','Uncertain classification records limited evidence rather than a confirmed cause.'],['Rarity alone proves the disease mechanism','Many rare variants are not disease-causing, so rarity is insufficient.'],['Every missense variant is definitively benign','Missense variants can have diverse functional effects.'],['The finding automatically explains all symptoms','Causal attribution requires evidence beyond the mere presence of a variant.']],
'A variant of uncertain significance lacks enough evidence for a confident pathogenic or benign classification. Rarity and a plausible gene are insufficient by themselves. Segregation, functional data, population evidence, and other findings may later permit reclassification, but uncertainty must remain explicit meanwhile.','Interpret uncertain variant classification without treating rarity as proof of causality.','missense variant type'),
q('Genetics','General Principles','Recessive variant phase in trans',3,'Two pathogenic variants are found in an autosomal recessive gene. Parental testing shows one was inherited from each parent on opposite homologues. What does this establish?',[
['The variants are in trans','Opposite homologues can each carry a disrupted allele of the recessive gene.'],['Both variants must be on one chromosome','Separate parental homologues indicate trans rather than cis phase.'],['A dominant mechanism is mandatory','Biallelic variants are compatible with a recessive mechanism.'],['Every neighboring gene is also deleted','Sequence variants do not establish a contiguous gene deletion.']],
'Phase describes whether variants occupy the same homologue or opposite homologues. One variant on each parental chromosome establishes trans configuration and can support biallelic involvement in a recessive disorder. Two variants in cis may instead leave the other allele intact, changing interpretation.','Use parental origin to distinguish trans from cis variants in a recessive gene.','autosomal recessive recurrence probability'),
q('Genetics','General Principles','Pseudogene sequence misalignment',3,'Short sequencing reads map equally well to a functional gene and a highly similar inactive copy. An apparent pathogenic call disappears with locus-specific testing. What most likely occurred?',[
['Misalignment to a homologous pseudogene','Highly similar sequences can cause reads from one locus to be assigned to another.'],['Universal reversion of the variant in every cell','A technical mapping explanation fits the locus-specific discrepancy better.'],['A necessary change in the persons parentage','Read mapping error does not imply a biological relationship change.'],['Proof that all sequencing is useless','A locus-specific artifact does not invalidate every sequencing method.']],
'Pseudogenes can share extensive sequence identity with functional genes. Short reads may be assigned incorrectly, creating false variant calls at the functional locus. Locus-specific amplification or other validated methods can distinguish the sequences and resolve the apparent finding.','Infer pseudogene misalignment from homologous reads and locus-specific confirmation.','PCR allele dropout artifact'),
q('Genetics','General Principles','Linkage disequilibrium association',2,'A common marker is associated with a disease because it is often inherited with a nearby causal variant. The marker itself has no demonstrated functional effect. Which explanation fits?',[
['Linkage disequilibrium with the causal variant','Nonrandom co-inheritance can make a marker associate without being mechanistically causal.'],['Association proves direct protein disruption by the marker','A statistical association alone does not establish a functional mechanism.'],['Every associated allele must be on a different chromosome','Nearby variants can be inherited together on the same chromosome.'],['A marker can never predict anything unless it is causal','Correlated inheritance can produce predictive association without direct causation.']],
'Nearby variants may occur together more often than expected because of shared inheritance history and limited recombination. A marker can therefore track a causal allele without altering biological function itself. Functional or fine-mapping evidence is needed to distinguish the associated marker from the causal change.','Distinguish linked marker association from direct variant causality.','genetic variant evidence interpretation'),
q('Genetics','General Principles','De novo constitutional variant',2,'A child has a heterozygous variant present across tested tissues but absent from both parents routine samples. Which origin is compatible with this apparently de novo finding?',[
['A new variant in a parental gamete or very early embryo','An early event can produce a broadly distributed variant absent from parental blood.'],['Mandatory inheritance from an affected grandparent','An apparently new variant does not require an affected grandparent.'],['Only infection of the child with a DNA virus','A constitutional sequence variant need not result from infection.'],['Proof that sibling recurrence risk is absolutely zero','Possible parental germline mosaicism prevents that absolute inference.']],
'A de novo variant may arise in a gamete or early after fertilization and be absent from routine parental samples. Broad tissue distribution supports an early event but does not determine its exact timing. Germline mosaicism remains one reason not to infer an absolute zero recurrence risk.','Identify plausible early origins of an apparently de novo constitutional variant.','gonadal mosaic recurrence'),
q('Genetics','General Principles','Pleiotropic gene effects',1,'A pathogenic variant in one extracellular matrix gene affects the skeleton, eyes, and cardiovascular system. Which term describes multiple organ effects from one gene?',[
['Pleiotropy','One gene can influence multiple distinct phenotypic traits or organ systems.'],['Locus heterogeneity','That refers to different genes producing a similar phenotype rather than one gene affecting many organs.'],['Allelic exclusion','Allelic exclusion restricts receptor expression and does not describe multisystem effects.'],['Complete nonpenetrance','The stem describes multiple manifestations rather than absent disease features.']],
'Pleiotropy occurs when one gene contributes to several phenotypic traits. A widely used matrix component can affect multiple tissues through shared structural functions. This differs from locus heterogeneity, where different genes converge on a similar phenotype.','Recognize multiple organ effects of a single gene as pleiotropy.','locus heterogeneity'),
q('Microbiology','General Principles','Naked DNA transformation',2,'Bacteria acquire a new trait after exposure to purified donor DNA. Adding DNase before exposure prevents transfer, and no phage or cell contact is needed. Which mechanism fits?',[
['Transformation','Competent bacteria can take up extracellular DNA that is vulnerable to DNase.'],['Conjugation','Conjugation requires donor-recipient interaction rather than purified naked DNA alone.'],['Generalized transduction','Transduction uses a phage carrier rather than unprotected extracellular DNA.'],['Spontaneous mutation as the sole mechanism','Dependence on donor DNA and DNase sensitivity support acquisition rather than chance mutation alone.']],
'Transformation introduces extracellular DNA into a competent bacterium. DNase can destroy exposed donor DNA before uptake, preventing transfer. The absence of required donor contact or a phage carrier distinguishes this process from conjugation and transduction.','Use DNase sensitivity and carrier independence to identify bacterial transformation.','plasmid conjugation'),
q('Microbiology','General Principles','Generalized phage transduction',3,'A bacteriophage particle accidentally packages random donor bacterial DNA and transfers a metabolic gene to a recipient. Many different loci can be transferred. Which mechanism is shown?',[
['Generalized transduction','Packaging errors can transfer varied bacterial loci through a phage carrier.'],['Specialized transduction','Specialized transfer favors loci adjacent to a particular prophage integration site.'],['Naked DNA transformation','The DNA is carried in a phage particle rather than taken up unprotected.'],['Conjugation','The experiment does not require direct donor-recipient conjugative contact.']],
'Generalized transduction results when phage packaging includes bacterial DNA instead of the usual viral genome. Different donor regions can be transferred through such particles. Random locus transfer and a phage carrier together distinguish it from specialized transduction and transformation.','Integrate random locus transfer with phage carriage to identify generalized transduction.','bacterial conjugation'),
q('Microbiology','General Principles','Specialized prophage excision transfer',3,'A temperate phage excises incorrectly from a bacterial chromosome and carries a nearby host gene. Only genes adjacent to its insertion site are transferred. What process is this?',[
['Specialized transduction','Imprecise prophage excision transfers selected neighboring bacterial genes.'],['Generalized transduction','Generalized packaging can transfer many loci without the same insertion-site restriction.'],['Transformation','The transfer described depends on a phage rather than naked DNA uptake.'],['Binary fission','Cell division alone does not explain a phage moving a neighboring gene to another cell.']],
'A prophage occupies a specific chromosomal site. Imprecise excision can include adjacent bacterial DNA, producing a specialized transducing particle. The restricted host gene set reflects the integration position, unlike the broad locus range of generalized transduction.','Infer specialized transduction from prophage excision and neighboring-gene restriction.','generalized transduction'),
q('Microbiology','General Principles','Lysogenic toxin conversion',2,'A bacterium becomes toxigenic only after a temperate phage establishes a prophage carrying the toxin gene. Which term describes this acquired phenotype?',[
['Lysogenic conversion','Expression of a phage-encoded gene changes the bacterial phenotype.'],['Pure chromosomal nondisjunction','Chromosome segregation failure does not explain the phage-supplied toxin gene.'],['Loss of every bacterial gene','The bacterium retains its genome and gains expression of an additional phage gene.'],['Transformation by free toxin protein','The trait is genetically encoded by a prophage rather than inherited as free toxin.']],
'Temperate phages can persist as prophages and encode products that alter bacterial behavior. A toxin encoded by the phage can make the lysogen toxigenic, called lysogenic conversion. This differs from transduction of a donor bacterial gene carried accidentally by the phage.','Distinguish phage-encoded toxin conversion from transfer of donor bacterial genes.','bacterial conjugation'),
q('Microbiology','General Principles','Capsule antiphagocytic role',2,'Two otherwise matched bacterial strains differ only in capsule production. The encapsulated strain resists uptake by phagocytes before specific opsonizing antibody appears. Why?',[
['The capsule impedes efficient phagocytic recognition and uptake','Surface polysaccharide can shield targets that would otherwise support engulfment.'],['The capsule replaces all bacterial ribosomes','Capsules are surface structures rather than protein-synthesis machinery.'],['Capsules necessarily generate ATP','Capsular polysaccharides are not the main bacterial energy-generating organelles.'],['Every capsule directly destroys phagocyte DNA','Antiphagocytic shielding does not require direct nuclear DNA destruction.']],
'Capsules can impede attachment and engulfment by phagocytes. Opsonizing antibodies and complement improve recognition of encapsulated organisms and may overcome this barrier. The experiment isolates a surface defense mechanism rather than a change in bacterial metabolism or a universal toxin action.','Explain capsule-associated resistance to unopsonized phagocytosis.','C3b-mediated opsonization'),
q('Microbiology','General Principles','Mucosal bacterial IgA protease',2,'A mucosal bacterium releases a protease that cleaves secretory IgA near its hinge region. Which host defense is most directly weakened?',[
['Antibody-mediated mucosal exclusion','IgA helps prevent microbial adherence and penetration at mucosal surfaces.'],['Mitochondrial ATP generation','IgA cleavage does not directly disable mitochondrial respiratory enzymes.'],['Chromosomal replication in every host cell','The protease targets antibody rather than host DNA polymerization.'],['Erythrocyte oxygen binding','Secretory IgA is not hemoglobin and its cleavage does not directly remove oxygen sites.']],
'Secretory IgA protects mucosal surfaces partly by limiting adherence and access to epithelium. Bacterial IgA proteases can compromise this local antibody barrier. The mechanism targets immune exclusion at the mucosa rather than class switching or systemic complement pore assembly.','Connect bacterial IgA proteolysis with impaired mucosal immune exclusion.','secretory IgA epithelial transport'),
q('Microbiology','General Principles','Biofilm matrix persistence',2,'Bacteria on a synthetic surface form a matrix-embedded community and become harder to eradicate than free-floating cells of the same strain. Which feature contributes?',[
['Matrix-associated community physiology and reduced susceptibility','Biofilms alter access, growth states, and local conditions that affect eradication.'],['Proof of a new resistance mutation in every organism','Biofilm tolerance does not require an identical new mutation in every cell.'],['Absence of every extracellular polymer','An extracellular matrix is a defining feature of the described community.'],['Conversion of all bacteria into viruses','Surface community growth does not require a change into viral particles.']],
'Biofilms contain microbes embedded in an extracellular matrix with heterogeneous nutrient and growth conditions. Matrix barriers and slow-growing or persistent subpopulations can reduce susceptibility. This phenotype does not itself establish a specific inherited drug-resistance mutation.','Explain biofilm persistence without assuming universal new resistance mutations.','bacterial capsule shielding'),
q('Microbiology','General Principles','Quorum sensing density signal',2,'A bacterial population activates a virulence program only after a diffusible self-produced signal accumulates at high cell density. Which regulatory process is demonstrated?',[
['Quorum sensing','Accumulated signaling molecules coordinate gene expression with population density.'],['Human antibody affinity maturation','The response occurs within bacteria rather than host germinal-center B cells.'],['Mandatory horizontal gene acquisition','Density-dependent expression can occur without acquiring new genes.'],['Random chromosome loss','The coordinated threshold response does not require random loss of chromosomes.']],
'Quorum sensing uses released signaling molecules whose local concentration often increases with bacterial density. Receptor-dependent detection changes gene expression across the community. The mechanism regulates an existing genetic program rather than necessarily creating a new mutation or transferring a gene.','Identify density-dependent bacterial gene regulation through quorum sensing.','bacterial genetic transfer'),
q('Microbiology','General Principles','Siderophore iron scavenging',2,'A bacterium grows in an iron-poor host environment by secreting small molecules that bind ferric iron tightly and are then recovered through specific receptors. What are these molecules?',[
['Siderophores','Siderophores scavenge iron and support microbial acquisition of this limited nutrient.'],['Immunoglobulins','Bacteria do not produce host immunoglobulins as their iron-scavenging system.'],['Peptidoglycan monomers','Cell-wall building blocks are not the characteristic secreted iron chelators.'],['Thyroid hormones','These endocrine molecules are not the bacterial iron uptake molecules described.']],
'Hosts restrict accessible iron as part of nutritional immunity. Bacterial siderophores bind ferric iron with high affinity, and uptake systems recover the iron-containing complexes. This supplies an essential nutrient and can contribute to virulence without directly lysing the host cell.','Explain siderophore-mediated microbial acquisition of host-restricted iron.','iron sequestration in inflammation'),
q('Microbiology','Gastrointestinal','Urease ammonia generation',2,'A gastric bacterium hydrolyzes urea to generate ammonia near its surface. Which local effect most directly helps it persist in the acidic stomach?',[
['Buffering of the nearby acidic environment','Ammonia accepts protons and can raise local pH around the organism.'],['Complete removal of all gastric oxygen','Urea hydrolysis does not require total elimination of gastric oxygen.'],['Direct conversion of urea into peptidoglycan','Urease does not directly assemble the bacterial cell wall from urea.'],['Universal prevention of host inflammation','Urease-associated persistence does not guarantee absence of inflammation.']],
'Urease breaks down urea, producing ammonia and carbon dioxide. Ammonia can buffer nearby hydrogen ions, supporting survival in an acidic niche. This is a local biochemical adaptation rather than complete neutralization of the entire stomach or proof that the organism is harmless.','Link bacterial urease activity to local acid buffering.','gastric proton secretion'),
q('Microbiology','General Principles','Catalase bubble test',1,'A bacterial colony produces immediate oxygen bubbles when hydrogen peroxide is added. Which enzyme activity is being detected by this laboratory test?',[
['Catalase','Catalase decomposes hydrogen peroxide into water and oxygen gas.'],['Coagulase','Coagulase promotes clotting-related reactions rather than peroxide decomposition.'],['Urease','Urease hydrolyzes urea and does not generate the peroxide test bubbles.'],['Beta-galactosidase','This enzyme hydrolyzes lactose-related substrates rather than hydrogen peroxide.']],
'Catalase converts hydrogen peroxide into water and molecular oxygen. Visible bubbles therefore indicate peroxide decomposition by the organism. The result is one identification feature and should be integrated with morphology and other tests rather than treated as a complete species diagnosis.','Identify catalase activity from peroxide-associated oxygen bubble formation.','staphylococcal coagulase identification'),
q('Microbiology','General Principles','Pilus antigenic variation',2,'Successive isolates from a persistent mucosal infection express antigenically different pili despite originating from the same bacterial lineage. Which advantage can this provide?',[
['Escape from previously generated anti-pilus antibodies','Changing exposed antigenic sequences can reduce recognition by existing antibodies.'],['Permanent loss of every adhesion function','Antigenic variation need not abolish the ability of pili to support adherence.'],['Immediate immunity to all antibiotics','Antigen changes do not automatically create universal antibiotic resistance.'],['Conversion of the organism into a fungus','Variation of a bacterial surface structure does not change its biological kingdom.']],
'Surface antigen variation can alter epitopes recognized by a previously formed antibody response. A bacterial lineage may therefore persist despite immune recognition of an earlier variant. This mechanism concerns changing antigenic identity rather than merely producing a thicker capsule or acquiring an antibiotic-resistance plasmid.','Explain antibody evasion through bacterial pilus antigenic variation.','influenza reassortment'),
q('Microbiology','General Principles','Obligate anaerobe oxygen toxicity',2,'A bacterium grows well without oxygen but poorly when exposed to air because reactive oxygen species overwhelm its defenses. Which explanation best fits its oxygen sensitivity?',[
['Inadequate detoxification of reactive oxygen species','Limited protective enzymes permit oxygen-derived radicals and peroxide to accumulate.'],['An absolute requirement to use oxygen as final acceptor','Such a requirement would not explain growth only in oxygen-free conditions.'],['Absence of every genetic material','A growing bacterium necessarily retains genetic information.'],['Direct conversion of oxygen into its capsule','Capsule production does not explain the stated oxidant toxicity.']],
'Oxygen exposure can generate superoxide and hydrogen peroxide during cellular reactions. Organisms with insufficient protective systems may accumulate damaging oxidants and fail to grow in air. Anaerobic physiology is diverse, so enzyme limitations explain this stated experiment without asserting one rule for every anaerobe.','Connect the stated anaerobic oxygen sensitivity with deficient oxidant detoxification.','bacterial spore resistance'),
q('Microbiology','Respiratory','Mycoplasma absent wall',2,'A respiratory isolate has no peptidoglycan wall but retains a sterol-containing plasma membrane. Which structural feature explains its intrinsic insensitivity to wall-synthesis inhibitors?',[
['Absence of the peptidoglycan target','A drug cannot block a wall-assembly process that the organism does not possess.'],['An unusually thick peptidoglycan wall','The organism explicitly lacks this wall rather than thickening it.'],['A human nuclear envelope','The isolate remains a bacterium and does not acquire a human nucleus.'],['Mandatory beta-lactamase production as the only mechanism','No enzyme is needed when the targeted structure itself is absent.']],
'Mycoplasmas lack a peptidoglycan cell wall and depend on a membrane containing sterols. Wall-synthesis inhibitors therefore lack their usual target. This intrinsic structural explanation differs from an acquired enzyme that destroys a drug or a mutation in an otherwise present wall enzyme.','Explain target absence as the basis of mycoplasmal wall-drug insensitivity.','beta-lactam peptidoglycan action'),
q('Microbiology','General Principles','Chlamydia elementary body entry',1,'An intracellular bacterium alternates between a small infectious extracellular form and a larger replicating intracellular form. Which form initiates a new chlamydial infection?',[
['Elementary body','The elementary body is the infectious form that enters a new host cell.'],['Reticulate body','Reticulate bodies are adapted for intracellular replication rather than extracellular infection.'],['Bacterial endospore','Chlamydiae use a distinct developmental cycle rather than a classical endospore stage.'],['Fungal conidium','A conidium is a fungal reproductive structure rather than a chlamydial developmental form.']],
'Chlamydial elementary bodies are adapted for transmission and entry into host cells. Inside an inclusion they differentiate into reticulate bodies that replicate, then later convert back to elementary bodies. Separating infective and replicative forms explains the biphasic developmental cycle.','Identify the elementary body as the infectious chlamydial form.','bacterial endospores'),
q('Microbiology','Cardiovascular','Rickettsial endothelial tropism',2,'A rickettsial infection produces vascular leakage and widespread small-vessel inflammation. Infection of which host cell type most directly explains this vascular pathology?',[
['Endothelial cells','Rickettsial infection of vascular endothelium promotes injury and increased permeability.'],['Only mature erythrocytes','Red-cell restriction would not directly account for widespread endothelial inflammation.'],['Only pancreatic beta cells','Pancreatic cell injury does not explain the principal small-vessel process.'],['Only epidermal melanocytes','Pigment-cell infection does not directly generate the stated systemic vasculopathy.']],
'Many pathogenic rickettsiae preferentially infect vascular endothelial cells. Injury and inflammatory responses disrupt barrier function, producing leakage and small-vessel pathology. This links cellular tropism to systemic manifestations rather than assuming the rash alone identifies a species.','Connect rickettsial endothelial infection with vascular leakage and inflammation.','malaria erythrocyte life cycle'),
q('Microbiology','Respiratory','Legionella replication vacuole',2,'An inhaled bacterium survives inside alveolar macrophages by remodeling its vacuole and avoiding normal degradative trafficking. Which virulence strategy does this illustrate?',[
['Intracellular niche modification','The organism alters its host compartment to support survival and replication.'],['Obligatory extracellular growth without host entry','The stem explicitly describes survival after macrophage uptake.'],['A protective human immunoglobulin capsule','The organism does not synthesize a human antibody capsule for its vacuole.'],['Complete elimination of all macrophage metabolism','Intracellular replication depends on a usable host environment rather than total metabolic loss.']],
'Legionella delivers bacterial effectors that remodel the phagosomal compartment into a replication-supporting niche. Avoidance of normal degradative trafficking permits intracellular survival. The mechanism differs from simply resisting phagocytosis outside the cell or killing every macrophage before replication begins.','Explain Legionella survival through modification of an intracellular replication compartment.','bacterial capsule uptake resistance'),
q('Microbiology','General Principles','Listeria actin cell-to-cell spread',2,'An intracellular bacterium forms an actin tail and moves into a neighboring cell through membrane protrusions. Which advantage does this Listeria strategy provide?',[
['Spread with limited extracellular exposure','Actin-driven direct spread can reduce time exposed to extracellular antibodies.'],['Avoidance of every cellular immune response','Intracellular spread does not make the organism invisible to all T-cell defenses.'],['Replacement of bacterial DNA by host actin','Actin provides motility rather than replacing the microbial genome.'],['Conversion into a nonreplicating endospore','This is active intracellular movement rather than a dormant spore transition.']],
'Listeria can recruit host actin polymerization to drive cytoplasmic motility and protrusion into adjacent cells. Direct spread limits exposure to extracellular immune factors while extending infection. It remains susceptible to cellular defenses, so reduced antibody exposure does not mean complete immune escape.','Explain the immune-exposure advantage of actin-driven Listeria cell-to-cell spread.','fibroblast actin motility'),
q('Microbiology','General Principles','Diphtheria EF2 inactivation',2,'A bacterial A-B toxin enters a host cell and ADP-ribosylates elongation factor 2. Which essential cellular process is most directly impaired?',[
['Ribosomal protein elongation','EF-2 is needed for translocation during eukaryotic protein synthesis.'],['DNA ligation only','EF-2 is a translation factor rather than the enzyme sealing DNA breaks.'],['Intestinal lactose hydrolysis','Lactase activity is not the direct EF-2-dependent process.'],['Mitochondrial fatty acid entry','Carnitine transport does not depend directly on cytosolic EF-2 translocation.']],
'Diphtheria toxin transfers ADP-ribose to a modified residue on EF-2, inactivating its translation function. Ribosomal translocation fails and protein synthesis declines. The catalytic A domain therefore causes injury through a defined host target rather than through nonspecific bacterial wall inflammation.','Link diphtheria toxin EF-2 modification to inhibition of protein elongation.','Shiga toxin ribosomal RNA injury'),
q('Microbiology','Respiratory','Pertussis inhibitory G protein block',2,'A bacterial toxin locks Gi proteins in an inactive state by ADP-ribosylation. Which signaling effect is expected in an appropriately responsive host cell?',[
['Reduced inhibition of adenylyl cyclase with increased cAMP','Inactivating Gi removes a normal inhibitory influence on cAMP production.'],['Permanent activation of Gi with suppressed cAMP','The stem specifies inactive rather than persistently active Gi.'],['Direct cleavage of all ribosomal RNA','Gi modification is distinct from toxin-mediated ribosomal damage.'],['Obligatory inhibition of every protein kinase','Increased cAMP can activate downstream signaling rather than stopping all kinases.']],
'Pertussis toxin ADP-ribosylates inhibitory G proteins and prevents normal receptor-mediated Gi activation. Loss of the inhibitory brake can increase adenylyl cyclase activity and cAMP. This differs from cholera toxin, which stimulates the pathway by maintaining Gs in an active state.','Distinguish Gi inactivation from Gs activation as routes to increased cAMP.','cholera toxin Gs activation'),
q('Microbiology','General Principles','Anthrax edema factor cyclase',2,'An anthrax toxin component enters a host cell and binds calmodulin, greatly increasing cyclic AMP. What enzymatic activity does this edema factor provide?',[
['Calmodulin-dependent adenylyl cyclase','Edema factor directly catalyzes cAMP generation after activation by host calmodulin.'],['DNA-dependent RNA polymerase','The described product is cAMP rather than an RNA transcript.'],['EF-2-specific protease','Edema factor is not the EF-2-directed protein synthesis inhibitor.'],['Host actin depolymerase exclusively','Its principal enzymatic effect here is cyclic nucleotide production.']],
'Anthrax edema factor is a bacterial adenylyl cyclase activated by host calmodulin after cell entry. Excess cAMP disrupts normal cellular regulation and contributes to edema. This direct enzyme delivery differs from toxins that raise cAMP by modifying host G proteins.','Identify edema factor as a delivered calmodulin-dependent adenylyl cyclase.','cholera and pertussis G-protein modification'),
q('Microbiology','General Principles','Viral envelope detergent vulnerability',2,'Two viruses have similar capsids, but one also requires an intact lipid envelope for entry. A lipid-disrupting detergent preferentially inactivates the enveloped virus. Why?',[
['Disruption of envelope-dependent entry structures','Destroying the lipid envelope can disorganize essential attachment and fusion machinery.'],['Detergent always selectively deletes RNA genomes','Lipid disruption is not universally selective for RNA rather than DNA.'],['Nonenveloped viruses contain no proteins','All ordinary viruses retain protein components such as their capsid.'],['The envelope is a peptidoglycan wall','Viral envelopes are lipid membranes rather than bacterial cell walls.']],
'An enveloped virus relies on a host-derived lipid membrane carrying viral entry proteins. Detergent disruption can destroy the organization needed for attachment or fusion. The effect follows envelope dependence rather than whether the viral genome is RNA or DNA, and susceptibility varies with conditions.','Explain selective vulnerability of required viral lipid envelopes to detergent disruption.','bacterial peptidoglycan structure'),
q('Microbiology','General Principles','Positive sense RNA initial translation',2,'Purified genomic RNA from a nonretroviral positive-sense RNA virus enters a permissive cell and can direct viral protein synthesis. Why can translation begin from this RNA?',[
['Its sequence orientation functions as messenger RNA','Positive-sense genomic RNA can serve directly as a ribosomal translation template.'],['Host ribosomes translate all negative-sense RNA directly','Negative-sense genomes generally require a complementary messenger RNA first.'],['Every RNA must first integrate into a chromosome','Direct translation of this genome does not require chromosomal integration.'],['The RNA is itself a complete ribosome','A viral genome provides coding information rather than becoming a ribosome.']],
'A conventional positive-sense RNA genome has the coding orientation needed for translation. After uncoating in a suitable cell, it can direct synthesis of viral proteins, including replication machinery. New genome replication still requires additional steps, so immediate translation is not equivalent to an already complete replication cycle.','Identify messenger-sense viral RNA as a direct initial translation template.','influenza segmented genome reassortment'),
q('Microbiology','General Principles','Negative sense packaged polymerase',2,'A negative-sense RNA virus enters a cell. Its genome cannot be translated directly. Which enzyme must the incoming particle generally supply to begin viral messenger RNA synthesis?',[
['RNA-dependent RNA polymerase','The incoming polymerase copies negative-sense genomic RNA into translatable RNA.'],['Host DNA ligase','DNA ligase does not transcribe an RNA genome into messenger RNA.'],['Pancreatic amylase','A digestive enzyme cannot produce viral transcripts from RNA.'],['Telomerase as the general solution','Telomerase maintains DNA ends rather than transcribing negative-sense viral genomes.']],
'Negative-sense RNA is complementary to messenger RNA and cannot directly serve as the needed translation template. Host cells lack a general RNA-dependent RNA polymerase for this task. The virion therefore packages polymerase activity to generate viral transcripts after entry.','Explain why negative-sense RNA virions must carry transcriptional polymerase activity.','positive-sense RNA translation'),
q('Microbiology','General Principles','Retroviral DNA integration',2,'An RNA virus makes a DNA copy of its genome and then inserts that copy into a host chromosome. Which viral enzyme catalyzes the chromosomal insertion step?',[
['Integrase','Integrase joins viral DNA ends to host chromosomal DNA during provirus formation.'],['Reverse transcriptase alone','Reverse transcriptase makes the DNA copy but is not the enzyme performing integration.'],['Neuraminidase','Neuraminidase cleaves sialic acids rather than inserting viral DNA into chromosomes.'],['Host lactase','Lactase digests lactose rather than forming a proviral integration junction.']],
'Retroviral reverse transcription produces DNA from the RNA genome. Integrase then catalyzes insertion of this viral DNA into a host chromosome, establishing a provirus. Separating the copying and insertion steps explains why two different viral enzyme activities are required.','Distinguish retroviral integrase insertion from reverse transcriptase DNA synthesis.','HIV receptor entry'),
q('Microbiology','General Principles','Hepatitis B RNA intermediate',2,'A DNA virus copies a pregenomic RNA intermediate back into DNA within assembling particles. Which replication feature identifies the unusual hepatitis B strategy?',[
['Reverse transcription during genome production','HBV uses an RNA intermediate despite carrying DNA in the infectious particle.'],['Absence of all RNA during replication','The stated pregenomic RNA is an essential intermediate.'],['Mandatory integration for every new virion','Productive HBV replication does not require chromosomal integration each cycle.'],['Replication exclusively by host DNA polymerase','A viral reverse transcriptase performs the RNA-to-DNA copying step.']],
'Hepatitis B virions carry a partially double-stranded DNA genome. Nuclear templates generate pregenomic RNA, which is reverse-transcribed during particle assembly. Genome type alone therefore does not predict that replication will use only conventional DNA-to-DNA copying.','Recognize HBV DNA production through a pregenomic RNA intermediate.','hepatitis B serology'),
q('Microbiology','Nervous System','Herpes neuronal episomal latency',2,'After a mucosal herpes infection resolves, viral DNA persists in sensory neurons with limited gene expression and no continuous release of virions. Which state is described?',[
['Latent episomal persistence','Herpes genomes can remain as nuclear episomes and later reactivate.'],['Obligatory productive lysis of every neuron','Latency permits persistence without continuous destruction of every infected cell.'],['Permanent absence of viral genetic material','The genome is explicitly retained in the neuron.'],['Bacterial endospore formation','Herpes persistence does not involve a bacterial spore structure.']],
'Herpes simplex can establish latency in sensory neurons, retaining its genome largely as a nuclear episome with restricted expression. Reactivation can later restore productive infection. Latency is therefore neither continuous high-level lytic replication nor complete eradication of the viral genome.','Identify restricted herpes genome persistence in sensory neurons as latency.','viral integration'),
q('Microbiology','Respiratory','Influenza antigenic drift substitutions',2,'An influenza lineage accumulates point mutations in surface antigen genes over several seasons without exchanging whole genome segments. Which process explains gradual antigenic change?',[
['Antigenic drift','Accumulated sequence substitutions can alter epitopes recognized by prior immunity.'],['Antigenic shift by reassortment','Whole segment exchange is explicitly absent from this scenario.'],['Bacterial conjugation','Influenza changes are not transferred through a bacterial mating bridge.'],['Genomic imprinting','Parent-of-origin gene silencing does not explain influenza epitope substitutions.']],
'Influenza antigenic drift reflects accumulation and selection of mutations that alter antigenic proteins. The resulting epitopes may be recognized less effectively by existing immunity. This gradual sequence change differs from antigenic shift associated with exchange of genome segments between strains.','Distinguish point-mutation antigenic drift from segment reassortment.','influenza reassortment'),
q('Microbiology','General Principles','Fungal membrane ergosterol',1,'A laboratory compares membrane sterols in a pathogenic fungus and a human cell. Which sterol is characteristic of the fungal membrane and differs from the principal human sterol?',[
['Ergosterol','Ergosterol is a major fungal membrane sterol and differs from human cholesterol.'],['Cholesterol as the unique fungal sterol','Cholesterol is the principal human membrane sterol rather than the distinguishing fungal one.'],['Peptidoglycan','Peptidoglycan is a bacterial wall polymer rather than a membrane sterol.'],['Glycogen','Glycogen is a carbohydrate storage polymer rather than a membrane sterol.']],
'Fungal plasma membranes commonly contain ergosterol as a major sterol, whereas human membranes principally use cholesterol. The chemical difference provides selective biological targets but does not mean every fungal component is unique. Membrane sterols also differ from structural cell-wall polysaccharides.','Identify ergosterol as a characteristic fungal membrane sterol.','Candida morphology'),
q('Microbiology','General Principles','Fungal beta glucan wall',1,'A fungal cell contains a rigid wall outside its plasma membrane. Which polysaccharide is an important wall component rather than a sterol in the underlying membrane?',[
['Beta glucan','Beta glucans contribute to fungal wall structure together with other polymers.'],['Ergosterol','Ergosterol is principally a membrane sterol rather than a wall polysaccharide.'],['Human collagen type I','Fungi do not use human collagen as the defining wall framework.'],['Bacterial lipopolysaccharide','LPS is associated with Gram-negative outer membranes rather than a typical fungal wall.']],
'Fungal walls contain structural polysaccharides including beta glucans and chitin, with composition varying by organism and stage. The plasma membrane beneath the wall contains ergosterol. Distinguishing these compartments prevents confusion between a wall polymer and a membrane lipid.','Distinguish fungal wall beta glucan from membrane ergosterol.','Gram-positive peptidoglycan wall'),
];
